-- Function: public.fn_get_experience_by_id
-- Backup generated on 2026-10-25 20:33:19

CREATE OR REPLACE FUNCTION public.fn_get_experience_by_id(p_tenant_id uuid, p_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, title character varying, description text, status character varying, dna_payload jsonb, created_by_user_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone, average_stars numeric)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT e.id, e.tenant_id, e.organization_id, e.title, e.description, e.status, e.dna_payload,            e.created_by_user_id, e.created_at, e.updated_at,            COALESCE(AVG(ef.stars), 0)::NUMERIC AS average_stars     FROM experiences e     LEFT JOIN experience_schedules es ON e.id = es.experience_id     LEFT JOIN experience_feedback ef ON es.id = ef.experience_schedule_id     WHERE e.id = p_id AND e.tenant_id = p_tenant_id     GROUP BY e.id, e.tenant_id, e.organization_id, e.title, e.description, e.status, e.dna_payload, e.created_by_user_id, e.created_at, e.updated_at; END; $function$ ;
